INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(25201, 'John 6:71', 'John', 6, 71, '&nbsp;هغۀ د شمعون اِسکريوتى د زوئ يهوداه په حقله خبره کوله کوم چې په دولسو مريدانو کښې يو وو، او وروستو يې د عيسىٰ مُخبرى هم وکړله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25202, 'John 7:1', 'John', 7, 1, '&nbsp;د دې نه پس عيسىٰ ګليل کښې ګېرچاپېره ګرځېدو. هغۀ يهوديه ته تلل نۀ غوښتل ځکه چې يهوديانو موقع لټوله چې هغه مړ کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25203, 'John 7:2', 'John', 7, 2, '&nbsp;اوس د يهوديانو د جونګړو اختر هم رانزدې وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25204, 'John 7:3', 'John', 7, 3, '&nbsp;نو د هغۀ خپلو وروڼو هغۀ ته ووئيل چې، ”تۀ دا علاقه پرېږده او يهوديه ته لاړ شه نو چې ستا مريدان هغه لوئ کارونه چې تۀ يې کوې، ووينى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25205, 'John 7:4', 'John', 7, 4, '&nbsp;ځکه څوک چې غواړى چې مشهور شى نو هغه پټ کارونه نۀ کوى. کۀ چرې تۀ دا کارونه کوې نو دُنيا ته ځان څرګند کړه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25206, 'John 7:5', 'John', 7, 5, '&nbsp;ځکه چې د هغۀ خپلو وروڼو هم په هغۀ باندې ايمان نۀ ساتلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25207, 'John 7:6', 'John', 7, 6, '&nbsp;عيسىٰ هغوئ ته وفرمائيل چې، ”زما دپاره مقرر شوے وخت لا نۀ دے راغلے، خو ستاسو دپاره هر وخت ټيک دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25208, 'John 7:7', 'John', 7, 7, '&nbsp;دُنيا تاسو نه نفرت نۀ شى کولے خو زما نه نفرت کوى ځکه چې زۀ د دې خلاف ګواهى ورکوم چې د دې کارونه بد دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25209, 'John 7:8', 'John', 7, 8, '&nbsp;تاسو په خپله اختر له لاړ شئ، زۀ دې اختر له نۀ ځم ځکه چې زما دپاره مقرر شوے وخت لا نۀ دے راغلے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25210, 'John 7:9', 'John', 7, 9, '&nbsp;د دې فرمائيلو نه پس عيسىٰ په ګليل کښې پاتې شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25211, 'John 7:10', 'John', 7, 10, '&nbsp;خو کله چې د عيسىٰ وروڼه اختر له لاړل نو هغه په خپله هم لاړو، خو په ښکاره نه بلکې په پټه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25212, 'John 7:11', 'John', 7, 11, '&nbsp;يهوديانو په اختر کښې د هغۀ لټون کولو او تپوس يې کولو چې، ”عيسىٰ چرته دے؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25213, 'John 7:12', 'John', 7, 12, '&nbsp;او په ګڼه کښې د هغۀ په حقله ګنګوسے روان وو. چا به وئيل چې، ”هغه ښۀ سړے دے،“ خو ځينو به وئيل چې، ”نه، هغه خلق بې‌لارې کوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25214, 'John 7:13', 'John', 7, 13, '&nbsp;خو بيا هم خلقو د هغۀ په حقله د يهوديانو د يرې په وجه ښکاره هيڅ نۀ شو وئيلے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25215, 'John 7:14', 'John', 7, 14, '&nbsp;کله چې اختر نيم تېر شو نو عيسىٰ د خُدائ کور ته لاړو او تعليم يې شروع کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25216, 'John 7:15', 'John', 7, 15, '&nbsp;يهوديان حېران شول او وې وئيل، ”دې سړى څنګه دومره عِلم حاصل کړو سره د دې چې دۀ خو تعليم نۀ دے کړے؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25217, 'John 7:16', 'John', 7, 16, '&nbsp;عيسىٰ جواب ورکړو، ”زما تعليم زما نۀ دے، بلکې دا د هغه چا دے چې زۀ يې رالېږلے يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25218, 'John 7:17', 'John', 7, 17, '&nbsp;هر څوک چې غواړى چې د خُدائ پاک رضا پوره کړى، هغه به په دې پوهه شى چې زما تعليم د خُدائ د طرفه دے، يا کۀ زۀ د خپل ځان نه تعليم ورکوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25219, 'John 7:18', 'John', 7, 18, '&nbsp;څوک چې د خپل ځان نه خبرې کوى هغه خپل عزت غواړى خو څوک چې د خپل رالېږونکى عزت غواړى هغه رښتينے انسان دے او په هغۀ کښې هيڅ ټګى نشته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25220, 'John 7:19', 'John', 7, 19, '&nbsp;ولې موسىٰ تاسو ته شريعت نۀ وو درکړے؟ خو تاسو کښې يو هم پرې عمل نۀ کوئ. تاسو ولې زما د مړ کولو موقع ګورئ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25221, 'John 7:20', 'John', 7, 20, '&nbsp;ګڼې جواب ورکړو، ”په تا پيريان ناست دى. څوک ستا د وژلو کوشش کوى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25222, 'John 7:21', 'John', 7, 21, '&nbsp;عيسىٰ جواب ورکړو، ”ما يوه معجزه وکړله او تاسو ټول حېران شوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25223, 'John 7:22', 'John', 7, 22, '&nbsp;خو موسىٰ تاسو ته د سنت کولو شريعت درکړو، اګر چې دا د موسىٰ د طرف نه نۀ وو بلکې د پلار نيکۀ د وخت نه راروان وو، او تاسو د سبت په ورځ ماشوم سنتوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25224, 'John 7:23', 'John', 7, 23, '&nbsp;کۀ تاسو د سبت په ورځ ماشوم سنتوئ د دې دپاره چې د موسىٰ شريعت مات نۀ شى نو بيا تاسو زما نه په دې وجه ولې خفه يئ چې ما د سبت په ورځ د يو سړى پوره بدن روغ کړو؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25225, 'John 7:24', 'John', 7, 24, '&nbsp;په ظاهرى صورت فېصله مۀ کوئ بلکې په اِنصاف سره فېصله کوئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25226, 'John 7:25', 'John', 7, 25, '&nbsp;په دې باندې د يروشلم څۀ خلقو دا وينا شروع کړه، ”ولې دا هغه سړے نۀ دے چې هغوئ يې د وژلو کوشش کوى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25227, 'John 7:26', 'John', 7, 26, '&nbsp;وګورئ، دے دلته کښې ښۀ په ډاګه لګيا دے او هغوئ ورته هيڅ نۀ وائى. ولې داسې خو نۀ ده چې زمونږ مشران په دې خبر شوى وى چې دے په رښتيا مسيح دے؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25228, 'John 7:27', 'John', 7, 27, '&nbsp;خو مونږ ته پته ده چې دا سړے د کوم ځائ دے خو هر کله چې مسيح راشى نو هيچا ته به پته نۀ وى چې د کوم ځائ دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25229, 'John 7:28', 'John', 7, 28, '&nbsp;بيا عيسىٰ چې کله د خُدائ په کور کښې تعليم ورکولو نو چغه يې کړه، ”تاسو ما پېژنئ او تاسو ته پته ده چې زۀ د کوم ځائ يم. خو زۀ په خپله مرضۍ نۀ يم راغلے. خو چا چې زۀ رالېږلے يم هغه رښتونے دے، او تاسو هغه نۀ پېژنئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25230, 'John 7:29', 'John', 7, 29, '&nbsp;زۀ هغه پېژنم ځکه چې زۀ د هغۀ نه راغلے يم او هغۀ په خپله زۀ رالېږلے يم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25231, 'John 7:30', 'John', 7, 30, '&nbsp;نو بيا ځينې مشرانو د هغۀ د نيولو کوشش وکړو خو هيچا هغۀ ته لاس وانۀ چولو ځکه چې د هغۀ مقرر شوے وخت لا نۀ وو راغلے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25232, 'John 7:31', 'John', 7, 31, '&nbsp;خو په ګڼه کښې ډېرو په هغۀ ايمان راوړو او هغوئ وئيل چې، ”کله چې مسيح راشى نو ولې هغه به د دې کس نه زياتې معجزې وکړى څۀ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25233, 'John 7:32', 'John', 7, 32, '&nbsp;فريسيانو د عيسىٰ په حقله د خلقو غورېدل واورېدل، نو مشرانو اِمامانو او فريسيانو، محافظان د هغۀ نيولو پسې ولېږل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25234, 'John 7:33', 'John', 7, 33, '&nbsp;بيا عيسىٰ وفرمائيل چې، ”زۀ به څۀ لږې مودې دپاره تاسو سره يم او بيا به زۀ هغۀ له لاړ شم چا چې زۀ رالېږلے يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25235, 'John 7:34', 'John', 7, 34, '&nbsp;تاسو به زما لټون کوئ خو ما به پېدا نۀ کړئ او چرته چې به زۀ يم هلته به تاسو نۀ شئ راتلے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25236, 'John 7:35', 'John', 7, 35, '&nbsp;نو يهوديانو يو تر بله ووئيل چې، ”دے چرته تلل غواړى چې مونږ به يې بيا نۀ شُو موندے؟ ولې دے غواړى چې د يونان هغه ښارونو ته لاړ شى چې په کښې زمونږ خلق اوسيږى، او يونانيانو ته تعليم ورکړى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25237, 'John 7:36', 'John', 7, 36, '&nbsp;د هغۀ د دې وينا نه مطلب څۀ دے چې، تاسو به زما لټون کوئ خو ما به پېدا نۀ کړئ او چرته چې به زۀ يم هلته به تاسو نۀ شئ راتلے؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25238, 'John 7:37', 'John', 7, 37, '&nbsp;د اختر په آخرى او د ټولو نه په لويه ورځ عيسىٰ ودرېدلو او په اوچت آواز يې وفرمائيل، ”کۀ څوک تږے وى هغه دې ما له راشى، هغه دې وڅښى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25239, 'John 7:38', 'John', 7, 38, '&nbsp;او څوک چې په ما ايمان راوړى، لکه چې صحيفې وائى، د ژوندون د اوبو سيندونه به د هغۀ نه بهيږى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25240, 'John 7:39', 'John', 7, 39, '&nbsp;عيسىٰ دا خبره د هغه روحُ القُدس په حقله وکړه، کوم چې په هغه چا نازلېدونکے وو چا چې په عيسىٰ ايمان راوړو، نو تر دغه وخته روحُ القُدس لا نازل شوے نۀ وو، ځکه چې عيسىٰ لا خپل جلال ته رسېدلے نۀ وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25241, 'John 7:40', 'John', 7, 40, '&nbsp;کله چې هغوئ د هغۀ دا خبرې واورېدې په ګڼه کښې ځينو ووئيل، ”يقيناً چې دا هغه پېغمبر دے د چا چې مونږ په طمع يُو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25242, 'John 7:41', 'John', 7, 41, '&nbsp;چا ووئيل چې، ”دا مسيح دے،“ او ځينو ووئيل چې، ”ولې مسيح به د ګليل نه راځى څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25243, 'John 7:42', 'John', 7, 42, '&nbsp;ولې صحيفې دا نۀ فرمائى چې مسيح به د داؤد د خاندان او د بيت‌لحم نه راځى، د هغه کلى نه چې داؤد په کښې اوسېدلے وو؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25244, 'John 7:43', 'John', 7, 43, '&nbsp;دغه شان د عيسىٰ په وجه په خلقو کښې بې‌اتفاقى پېدا شوله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25245, 'John 7:44', 'John', 7, 44, '&nbsp;په هغوئ کښې ځينو غوښتل چې ګرفتار يې کړى، خو هيچا هم هغۀ ته لاس وانۀ چولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25246, 'John 7:45', 'John', 7, 45, '&nbsp;بيا محافظان، مشرانو اِمامانو او فريسيانو له واپس راغلل او هغوئ ورته ووئيل چې، ”تاسو هغه ولې ځان سره رانۀ وستو؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25247, 'John 7:46', 'John', 7, 46, '&nbsp;محافظانو جواب ورکړو چې، ”هيڅکله هم چا داسې خبرې نۀ دى کړى څنګه يې چې دا سړے کوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25248, 'John 7:47', 'John', 7, 47, '&nbsp;فريسيانو ورته ووئيل چې، ”ولې هغۀ تاسو هم بې‌لارې کړئ څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25249, 'John 7:48', 'John', 7, 48, '&nbsp;زمونږ مشرانو او فريسيانو نه يو هم په هغۀ ايمان نۀ دے راوړے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25250, 'John 7:49', 'John', 7, 49, '&nbsp;خو دا ګڼه چې په شريعت نۀ پوهيږى لعنتيان دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25251, 'John 7:50', 'John', 7, 50, '&nbsp;بيا په هغوئ کښې نيکوديموس نومې يو سړى، يعنې هغه سړے چې يو ځل مخکښې عيسىٰ له راغلے وو، هغۀ ووئيل چې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25252, 'John 7:51', 'John', 7, 51, '&nbsp;”ولې شريعت مونږ ته دا اجازت راکوى څۀ چې ترڅو د يو کس بيان په خپله وانۀ ورُو او هغۀ ته د خبرو موقع ورنۀ کړُو نو ولې هغه مونږ مجرم کولے شُو څۀ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25253, 'John 7:52', 'John', 7, 52, '&nbsp;هغوئ جواب ورکړو، ”تۀ هم ګليلى يې څۀ؟ وګوره او صحيفې ولوله، نو تۀ به په خپله خبر شې چې يو نبى هم د ګليل نه نۀ راځى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25254, 'John 7:53', 'John', 7, 53, '&nbsp;نو بيا ټول خپلو کورونو ته واپس لاړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25255, 'John 8:1', 'John', 8, 1, '&nbsp;عيسىٰ د زيتون غر ته وختلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25256, 'John 8:2', 'John', 8, 2, '&nbsp;بله ورځ سحر وختى هغه بيا د خُدائ کور ته راغلو. ټول خلق ورته راغونډ شول، او هغه کښېناستو او هغوئ ته يې تعليم شروع کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25257, 'John 8:3', 'John', 8, 3, '&nbsp;د شرعې عالمانو او فريسيانو يوه ښځه راوسته څوک چې په زنا کښې نيولے شوې وه. او هغه يې په خپل مينځ کښې ودروله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25258, 'John 8:4', 'John', 8, 4, '&nbsp;او هغوئ هغۀ ته ووئيل چې، ”اُستاذه، دا ښځه په زنا کولو نيولے شوې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25259, 'John 8:5', 'John', 8, 5, '&nbsp;په شريعت کښې موسىٰ مونږ ته حکم کړے دے چې داسې ښځې دې سنګسار کړے شى. نو بيا تاسو په دې حقله څۀ وايئ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25260, 'John 8:6', 'John', 8, 6, '&nbsp;هغوئ د هغۀ د آزمېښت دپاره دا سوال وکړو چې هغوئ د هغۀ خلاف څۀ اِلزام پېدا کړى. خو عيسىٰ ټيټ شو او په زمکه يې په ګوته څۀ وليکل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25261, 'John 8:7', 'John', 8, 7, '&nbsp;کله چې هغوئ بار بار د هغۀ نه تپوس کولو نو هغه نېغ ودرېدو او ورته يې وفرمائيل چې، ”په تاسو کښې به په هغې وړومبے د کاڼى ګزار هغه څوک کوى چا چې کله هم ګناه نۀ وى کړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25262, 'John 8:8', 'John', 8, 8, '&nbsp;او هغه يو ځل بيا ښکته ټيټ شو او په زمکه يې څۀ وليکل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25263, 'John 8:9', 'John', 8, 9, '&nbsp;کله چې هغوئ دا خبره واورېده نو هغوئ يو يو بهر ووتلو، د ټولو نه اول مشران وتښتېدل، او عيسىٰ د هغې ښځې سره يواځې پاتې شو چې د هغۀ په وړاندې ولاړه وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25264, 'John 8:10', 'John', 8, 10, '&nbsp;عيسىٰ بيا ودرېدلو هغه ښځې ته يې وفرمائيل، ”هغوئ چرته لاړل؟ ولې تۀ هيچا هم مجرمه نۀ کړې څۀ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25265, 'John 8:11', 'John', 8, 11, '&nbsp;هغې جواب ورکړو، ”مالِکه، هيچا هم نه.“ او عيسىٰ وفرمائيل، ”او نۀ دې زۀ مجرمه کوم، ځه لاړه شه، خو بيا کله هم ګناه مۀ کوه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25266, 'John 8:12', 'John', 8, 12, '&nbsp;عيسىٰ بيا خلقو ته مخاطب شو او وې فرمائيل، ”زۀ د دُنيا نُور يم. څوک چې ما پسې راځى هغه به هيڅکله په تيارۀ کښې نۀ ګرځى بلکې هغه به د ژوندون رڼا ومومى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25267, 'John 8:13', 'John', 8, 13, '&nbsp;بيا فريسيانو هغۀ ته ووئيل، ”تۀ د خپل ځان په حق کښې ګواهى کوې خو ستا ګواهى اعتبارى نۀ ده.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25268, 'John 8:14', 'John', 8, 14, '&nbsp;عيسىٰ جواب ورکړو، ”زما ګواهى اعتبارى ده کۀ څۀ هم چې زۀ يې د ځان په حق کښې ورکوم، ځکه چې زۀ خبر يم چې زۀ چرته نه راغلے يم او چرته روان يم، خو تاسو ته پته نشته چې زۀ چرته نه راغلے يم او چرته ځم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25269, 'John 8:15', 'John', 8, 15, '&nbsp;تاسو په انسانى بنياد فېصلې کوئ خو زۀ د هيچا فېصله نۀ کوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25270, 'John 8:16', 'John', 8, 16, '&nbsp;خو کۀ چرې زۀ فېصله کوم نو زما فېصله به ټيک وى، ځکه چې زۀ يواځې نۀ يم کله چې فېصله کوم بلکې زۀ او زما پلار چې زۀ يې رالېږلے يم يې يو ځائ فېصله کوُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25271, 'John 8:17', 'John', 8, 17, '&nbsp;ستاسو په خپل شريعت کښې يې دا ليکلى دى چې د دوو کسانو ګواهى ټيک ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25272, 'John 8:18', 'John', 8, 18, '&nbsp;دا زۀ يم چې د خپل ځان په حقله ګواهى کوم او زما بل ګواه زما پلار دے چې زۀ يې رالېږلے يم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25273, 'John 8:19', 'John', 8, 19, '&nbsp;بيا هغوئ ترې تپوس وکړو، ”ستا پلار چرته دے؟“ عيسىٰ جواب ورکړو چې، ”تاسو نۀ خو ما پېژنئ او نۀ زما پلار. کۀ چرې تاسو زۀ پېژندے نو زما پلار به مو هم پېژندو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25274, 'John 8:20', 'John', 8, 20, '&nbsp;د خُدائ د کور په بيت‌المال کښې عيسىٰ دا خبره د تعليم ورکولو په وخت کښې وکړله، خو هيچا هم هغه ګرفتار نۀ کړو ځکه چې د هغۀ مقرر شوے وخت لا نۀ وو راغلے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25275, 'John 8:21', 'John', 8, 21, '&nbsp;عيسىٰ يو ځل بيا هغوئ ته وفرمائيل، ”زۀ درنه ځم، او تاسو به ما لټوئ خو تاسو به په خپلو ګناهونو کښې مړۀ شئ. او چرته چې زۀ ځم هلته تاسو نۀ شئ راتلے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25276, 'John 8:22', 'John', 8, 22, '&nbsp;بيا يهوديانو ووئيل، ”ولې دے به خپل ځان وژنى ځکه چې دے دا وائى، چرته چې زۀ ځم هلته تاسو نۀ شئ راتلے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25277, 'John 8:23', 'John', 8, 23, '&nbsp;نو عيسىٰ هغوئ ته وفرمائيل، ”تاسو د دې زمکې خلق يئ او زۀ د آسمان، تاسو د دې دُنيا اوسېدونکى يئ خو زۀ د دې دُنيا نۀ يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25278, 'John 8:24', 'John', 8, 24, '&nbsp;ځکه ما تاسو ته وفرمائيل چې تاسو به په خپلو ګناهونو کښې مړۀ شئ. کۀ چرې تاسو په دې باور نۀ کوئ چې زۀ هغه يم، يعنې، زۀ هم هغه پېغمبر يم نو تاسو به په خپلو ګناهونو کښې مړۀ شئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25279, 'John 8:25', 'John', 8, 25, '&nbsp;هغوئ د هغۀ نه تپوس وکړو، ”تۀ څوک يې؟“ عيسىٰ جواب ورکړو چې، ”زۀ هم هغه يم چې ما تاسو ته د اول نه وئيلى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25280, 'John 8:26', 'John', 8, 26, '&nbsp;ما سره ستاسو د مجرمولو او د وئيلو دپاره ډيرې خبرې دى خو هغه چا چې زۀ يې رالېږلے يم، رښتينے دے او څۀ چې ما د هغۀ نه اورېدلى دى هغه زۀ دُنيا ته وايم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25281, 'John 8:27', 'John', 8, 27, '&nbsp;هغوئ په دې پوهه نۀ شُو چې عيسىٰ هغوئ ته د خپل پلار په حقله خبرې کولې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25282, 'John 8:28', 'John', 8, 28, '&nbsp;نو عيسىٰ هغوئ ته وفرمائيل، ”کله چې تاسو اِبن آدم په سولۍ وخېژوئ نو بيا به تاسو پوهه شئ چې زۀ هغه يم، او زۀ په خپل اختيار هيڅ نۀ کوم خو زۀ هغه څۀ وايم، د څۀ چې پلار ما له تعليم راکړے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25283, 'John 8:29', 'John', 8, 29, '&nbsp;چا چې زۀ رالېږلے يم هغه ما سره دے. هغۀ زۀ يواځې نۀ يم پرېښے ځکه زۀ همېشه هغه څۀ کوم چې هغه پرې راضى کيږى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25284, 'John 8:30', 'John', 8, 30, '&nbsp;عيسىٰ چې دا خبرې کولې نو ډېرو پرې ايمان راوړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25285, 'John 8:31', 'John', 8, 31, '&nbsp;بيا عيسىٰ هغه يهوديانو ته وفرمائيل چا چې په هغۀ ايمان راوړے وو، ”کۀ چرې تاسو زما په کلام عمل کوئ نو تاسو به په رښتيا زما مريدان يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25286, 'John 8:32', 'John', 8, 32, '&nbsp;او تاسو به په حقيقت پوهه شئ او حقيقت به تاسو آزاد کړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25287, 'John 8:33', 'John', 8, 33, '&nbsp;هغوئ هغۀ ته جواب ورکړو چې، ”مونږ د اِبراهيم اولاد يُو، مونږ چرې هم د چا غلامان شوى نۀ يُو. ستا د دې وينا نه څۀ مطلب دے چې تاسو به آزاد شئ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25288, 'John 8:34', 'John', 8, 34, '&nbsp;عيسىٰ هغوئ ته وفرمائيل چې، ”زۀ تاسو ته رښتيا وايم، هر څوک چې ګناه کوى هغه د ګناه غلام دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25289, 'John 8:35', 'John', 8, 35, '&nbsp;غلام د يو خاندان فرد ګڼلے نۀ شى، خو زوئ همېشه دپاره د خاندان فرد ګڼلے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25290, 'John 8:36', 'John', 8, 36, '&nbsp;نو کۀ چرې زوئ تاسو آزاد کړى نو تاسو به په رښتيا سره آزاد يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25291, 'John 8:37', 'John', 8, 37, '&nbsp;ما ته پته ده چې تاسو د اِبراهيم اولاد يئ خو تاسو زما د وژلو موقع ګورئ ځکه چې ستاسو په زړونو کښې زما د کلام دپاره ځائ نشته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25292, 'John 8:38', 'John', 8, 38, '&nbsp;زۀ تاسو ته هغه وايم څۀ چې ما د پلار په حضور کښې ليدلى دى خو تاسو په هغې عمل کوئ څۀ چې تاسو د خپل پلار نه اورېدلى دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25293, 'John 8:39', 'John', 8, 39, '&nbsp;هغوئ ورته جواب ورکړو، ”اِبراهيم زمونږ پلار دے.“ عيسىٰ ورته وفرمائيل، ”کۀ چرې تاسو د اِبراهيم اولاد وئ نو تاسو به هغه کارونه کول کوم چې اِبراهيم کول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25294, 'John 8:40', 'John', 8, 40, '&nbsp;خو اوس تاسو کوشش کوئ چې ما ووژنئ ځکه چې ما تاسو ته حقيقت ووئيلو چې ما د خُدائ پاک نه اورېدلے وو. اِبراهيم هيڅکله هم داسې نۀ وُو کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25295, 'John 8:41', 'John', 8, 41, '&nbsp;تاسو د خپل پلار غوندې کارونه کوئ.“ هغوئ هغۀ ته ووئيل، ”مونږ حراميان نۀ يُو، او خُدائ پاک په خپله زمونږ پلار دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25296, 'John 8:42', 'John', 8, 42, '&nbsp;عيسىٰ ورته وفرمائيل چې، ”کۀ خُدائ پاک ستاسو پلار وے نو تاسو به ما سره مينه کولے ځکه چې زۀ د خُدائ پاک نه راغلے يم او اوس دلته يم. زۀ په خپله مرضۍ نۀ يم راغلے بلکې زۀ هغۀ رالېږلے يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25297, 'John 8:43', 'John', 8, 43, '&nbsp;تاسو ته چې زۀ څۀ وايم په هغې ولې نۀ پوهېږئ؟ دا ځکه چې تاسو زما کلام قبلولے نۀ شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25298, 'John 8:44', 'John', 8, 44, '&nbsp;خو تاسو د خپل پلار اِبليس بچى يئ او تاسو په خپله خوښه د هغۀ خواهشونه پوره کوئ. هغه د اول نه قاتل وو او په حقيقت نۀ دے ولاړ ځکه چې په هغۀ کښې څۀ حقيقت نشته. کله چې هغه دروغ وائى نو د خپل فطرت په مطابق يې وائى ځکه چې هغه دروغژن دے او د دروغو پلار دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25299, 'John 8:45', 'John', 8, 45, '&nbsp;نو کله چې زۀ تاسو ته رښتيا وايم خو تاسو په ما يقين نۀ کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25300, 'John 8:46', 'John', 8, 46, '&nbsp;په تاسو کښې څوک ما د ګناه مجرم ثابتولے شى؟ کۀ زۀ رښتيا وايم نو بيا ولې تاسو په ما يقين نۀ کوئ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');